import java.util.ArrayList; import java.util.Scanner; // Abstract class abstract class User { protected String name; User(String name) { this.name = name; } abstract void displayDetails(); } // Student class - Inheritance class Student extends User { private int score; Student(String name) { super(name); score = 0; } void addScore() { score++; } int getScore() { return score; } @Override void displayDetails() { System.out.println("Student Name : " + name); } } // Question class class Question { private String question; private String[] options; private int correctAnswer; Question(String question, String[] options, int correctAnswer) { this.question = question; this.options = options; this.correctAnswer = correctAnswer; } void displayQuestion() { System.out.println("\n" + question); for (int i = 0; i < options.length; i++) { System.out.println((i + 1) + ". " + options[i]); } } boolean checkAnswer(int answer) { return answer == correctAnswer; } } // Exam class class Exam { private ArrayList<Question> questions; Exam() { questions = new ArrayList<>(); questions.add(new Question( "Which language is mainly used for OOP?", new String[]{"HTML", "Java", "SQL", "CSS"}, 2)); questions.add(new Question( "Which keyword is used for inheritance in Java?", new String[]{"this", "super", "extends", "static"}, 3)); questions.add(new Question( "Which concept hides data?", new String[]{"Inheritance", "Encapsulation", "Polymorphism", "Compilation"}, 2)); questions.add(new Question( "Which keyword creates an object?", new String[]{"new", "class", "void", "return"}, 1)); questions.add(new Question( "Which method is the starting point of Java program?", new String[]{"start()", "run()", "main()", "execute()"}, 3)); } void startExam(Student student, Scanner sc) { System.out.println("\n========== ONLINE EXAM =========="); for (Question q : questions) { q.displayQuestion(); int answer; while (true) { try { System.out.print("Enter your answer (1-4): "); answer = sc.nextInt(); if (answer < 1 || answer > 4) { throw new Exception("Enter a number between 1 and 4."); } break; } catch (Exception e) { System.out.println("Invalid input! " + e.getMessage()); sc.nextLine(); } } if (q.checkAnswer(answer)) { System.out.println("Correct Answer!"); student.addScore(); } else { System.out.println("Wrong Answer!"); } } } } // Main class public class OnlineExaminationSystem { public static void main(String[] args) { Scanner sc = new Scanner(System.in); System.out.println("================================"); System.out.println("     ONLINE EXAMINATION SYSTEM"); System.out.println("================================"); System.out.print("Enter Student Name: "); String name = sc.nextLine(); Student student = new Student(name); student.displayDetails(); Exam exam = new Exam(); exam.startExam(student, sc); // Result System.out.println("\n========== EXAM RESULT =========="); System.out.println("Student Name : " + name); System.out.println("Total Marks  : 5"); System.out.println("Score        : " + student.getScore()); if (student.getScore() >= 3) { System.out.println("Result       } else { System.out.println("Result       } : PASS"); : FAIL"); System.out.println("================================="); sc.close(); } }